if (!process.env.INPUT_PATH) {
  throw new Error('Missing required env var INPUT_PATH');
}
globalThis.inputPath = process.env.INPUT_PATH;

const { readFileSync } = await import('node:fs');
const csvContent = readFileSync(globalThis.inputPath, 'utf8');
const mod = await import('papaparse');
const Papa = mod.default || mod;
if (typeof Papa.parse !== 'function') {
  throw new Error('papaparse: required method parse not in exports');
}
const parseResult = Papa.parse(csvContent, { header: true, skipEmptyLines: true });
if (!parseResult.meta || !Array.isArray(parseResult.meta.fields)) {
  throw new Error('Unexpected parse result shape');
}
const fields = parseResult.meta.fields;
const rows = parseResult.data;
let md = '';
// header
md += '| ' + fields.join(' | ') + ' |\n';
// separator
md += '| ' + fields.map(() => '---').join(' | ') + ' |\n';
// rows
for (const row of rows) {
  const line = fields.map(f => {
    const val = row[f];
    return val === undefined || val === null ? '' : String(val).replace(/\|/g, '\\|');
  }).join(' | ');
  md += '| ' + line + ' |\n';
}
globalThis.markdown = md.trim();

if (typeof globalThis.markdown !== 'string') {
  throw new Error('Markdown output not generated');
}
console.log(JSON.stringify({ markdown: globalThis.markdown }));
